-- ============================================================
-- 04 - Seed: resultados electorales 2015 por seccion (Nuevo Leon)
-- ============================================================
-- Generado automaticamente a partir de:
--   - DBs INE/Gobernador2015NuevoLeonSeccion.csv
--   - DBs INE/DiputadosMR2015NuevoLeonSeccion.csv
-- (resultados oficiales del INE 2015, nivel SECCION; no los de nivel
-- casilla). Ver 03-seed-geografia.sql para el detalle de las decisiones
-- de modelado (distritos, zero-padding, estrategia de insercion masiva).
--
-- No editar a mano: regenerar desde las fuentes si cambian.
-- Catalogo GLOBAL (sin tenant_id).
--
-- resultados_historicos: una fila por seccion/anio/eleccion/partido,
-- omitiendo partidos con 0 votos (para no inflar el archivo). Se incluyen
-- como "partido" tanto los partidos simples (PAN, PRI, ...) como las
-- coaliciones tal como las reporta el INE (ej. 'PRI_PVEM_NVA_ALIANZA_PD'),
-- los candidatos independientes (CAND_IND1..CAND_IND12 segun la eleccion)
-- y los votos para candidatos no registrados (columna NUM_VOTOS_CAN_NREG
-- del CSV, guardada aqui como partido='CAN_NREG').
--
-- resultados_seccion_totales: una fila por seccion/anio/eleccion con
-- lista_nominal, votos_validos, votos_nulos y total_votos.
-- ============================================================

create table if not exists resultados_historicos (
  id uuid primary key default gen_random_uuid(),
  seccion_id uuid not null references secciones(id),
  anio integer not null,
  eleccion text not null,
  partido text not null,
  votos integer not null default 0,
  creado_en timestamptz not null default now(),
  unique (seccion_id, anio, eleccion, partido)
);

create table if not exists resultados_seccion_totales (
  id uuid primary key default gen_random_uuid(),
  seccion_id uuid not null references secciones(id),
  anio integer not null,
  eleccion text not null,
  lista_nominal integer,
  votos_validos integer,
  votos_nulos integer,
  total_votos integer,
  creado_en timestamptz not null default now(),
  unique (seccion_id, anio, eleccion)
);

-- --- resultados_seccion_totales (5204 filas = 2602 secciones x 2 elecciones) ---
insert into resultados_seccion_totales (seccion_id, anio, eleccion, lista_nominal, votos_validos, votos_nulos, total_votos)
select s.id, 2015, v.eleccion, v.lista_nominal, v.votos_validos, v.votos_nulos, v.total_votos
from estados e
join secciones s on s.estado_id = e.id
